-- ── the event type ─────────────────────────────────────────────────────
do $constraints$
declare r record; v_def text;
begin
  for r in select * from (values
    ('events','events_type_check','type'),
    ('validation_policies','validation_policies_event_type_check','event_type')
  ) as c(table_name,constraint_name,column_name) loop
    select pg_get_constraintdef(oid) into v_def from pg_constraint
     where conrelid=('public.'||r.table_name)::regclass and conname=r.constraint_name;
    if v_def is null or position('CHECK (' in v_def) <> 1 then
      raise exception 'event type constraint anchor missing: %',r.constraint_name;
    end if;
    if position('payment_instructions_change' in v_def)=0 then
      execute format('alter table public.%I drop constraint %I',r.table_name,r.constraint_name);
      execute format('alter table public.%I add constraint %I ',r.table_name,r.constraint_name)
        || replace(v_def,'CHECK (',format('CHECK (%I = %L OR ',r.column_name,'payment_instructions_change'));
    end if;
  end loop;
end;
$constraints$;

-- Who reads the event: whoever may edit the payment methods (the owner holds
-- every permission). 0630's body, one branch more.
create or replace function public.event_type_view_permissions(p_type text)
returns text[] language sql immutable set search_path = public as $fn$
  select case
    when p_type in ('payment', 'adjustment', 'service_charge', 'invoice_payment',
                    'invoice_writeoff', 'invoice_reminder', 'invoice_issue',
                    'invoice_void', 'refund', 'usage_correction', 'usage_record_delete')
      then array['viewFinances', 'issueInvoices']
    when p_type in ('expense', 'expense_schedule', 'expense_repartition')
      then array['approveExpenses', 'viewFinances']
    when p_type in ('reservation', 'space_reservation', 'reservation_delete')
      then array['manageReservations']
    when p_type = 'quota'
      then array['manageReservations', 'viewFinances', 'issueInvoices']
    when p_type in ('member_join', 'member_status_change', 'subscription_change', 'role_change')
      then array['manageMembers']
    when p_type = 'matrix_change'
      then array['manageRoles', 'manageMembers']
    when p_type = 'price_negotiation'
      then array['viewNegotiations']
    when p_type = 'payment_terms_change'
      then array['paymentTermsEdit', 'viewNegotiations']
    when p_type = 'lease_change'
      then array['manageLease', 'viewFinances']
    when p_type = 'commitment_variance'
      then array['managePurchases', 'viewFinances']
    when p_type = 'badge_security_alert'
      then array['workspaceSettings']
    when p_type = 'payment_instructions_change'
      then array['manageIntegrations']
    else array['manageConfiguration']
  end;
$fn$;
revoke execute on function public.event_type_view_permissions(text) from public,anon;
grant execute on function public.event_type_view_permissions(text) to authenticated;

-- ── what a change of the bank account does ─────────────────────────────
-- Each field that differs, from -> to, over the stored account (an absent
-- field is ''). An IBAN is kept as the app shows one, upper case in groups of
-- four; a BIC upper case. An empty value clears the field. The revision is
-- the stored bank fields, so an edit of another way to pay does not stale a
-- proposal. A name this function is not given is left alone.
create or replace function public.payment_instructions_plan(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_keys constant text[] := array['iban', 'bic', 'bank_name', 'account_number', 'bank_code', 'qr_iban'];
  v_stored jsonb;
  v_now jsonb;
  v_new jsonb;
  v_changes jsonb := '[]'::jsonb;
  k text;
  v text;
begin
  select coalesce(w.payment_instructions, '{}'::jsonb) into v_stored
    from public.workspaces w where w.id = p_workspace_id;
  if v_stored is null then
    raise exception 'unknown workspace' using errcode = '22023';
  end if;
  select jsonb_object_agg(x, to_jsonb(coalesce(v_stored->>x, ''))) into v_now from unnest(v_keys) x;
  v_new := v_now;
  foreach k in array v_keys loop
    if not p_args ? k then continue; end if;
    if jsonb_typeof(p_args->k) <> 'string' then
      raise exception '% is a text', k using errcode = '22023';
    end if;
    v := btrim(p_args->>k);
    if v ~ '[[:cntrl:]]' or char_length(v) > (case k when 'bank_name' then 120 else 42 end) then
      raise exception '% is one short line', k using errcode = '22023';
    end if;
    if k in ('iban', 'qr_iban') then
      v := upper(regexp_replace(v, '\s', '', 'g'));
      if v <> '' and public.supplier_iban_check(v) <> 'valid' then
        raise exception '% is not a valid IBAN', k using errcode = '22023';
      end if;
      if k = 'qr_iban' and v <> '' and v !~ '^(CH|LI)[0-9]{2}3[01][0-9]{3}' then
        raise exception 'a QR-IBAN is a Swiss or Liechtenstein IBAN with an institution identifier from 30000 to 31999'
          using errcode = '22023';
      end if;
      v := btrim(regexp_replace(v, '(.{4})', '\1 ', 'g'));
    elsif k = 'bic' then
      v := upper(regexp_replace(v, '\s', '', 'g'));
      if v <> '' and v !~ '^[A-Z]{6}[A-Z0-9]{2}([A-Z0-9]{3})?$' then
        raise exception 'bic is 8 or 11 letters and digits' using errcode = '22023';
      end if;
    elsif k <> 'bank_name' and char_length(v) > 40 then
      raise exception '% is at most 40 characters', k using errcode = '22023';
    end if;
    v_new := jsonb_set(v_new, array[k], to_jsonb(v));
  end loop;
  foreach k in array v_keys loop
    if v_new->>k <> v_now->>k then
      v_changes := v_changes || jsonb_build_object('field', k, 'from', v_now->>k, 'to', v_new->>k);
    end if;
  end loop;
  return jsonb_build_object('changes', v_changes, 'revision', md5(v_now::text));
end;
$fn$;
revoke execute on function public.payment_instructions_plan(uuid, jsonb) from public, anon, authenticated;

create or replace function public.mcp_target_set_payment_instructions(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v jsonb;
begin
  perform public.mcp_setup_arguments(p_args, array['workspace_id', 'request_id',
    'iban', 'bic', 'bank_name', 'account_number', 'bank_code', 'qr_iban']);
  -- The Payment methods screen sits behind the money functionality: with it
  -- off nobody is asked (42501 is what the confirmation maps to not_exposed).
  if not public.feature_effective(p_workspace_id, 'moneyTab') then
    raise exception 'money is switched off in this space' using errcode = '42501';
  end if;
  v := public.payment_instructions_plan(p_workspace_id, p_args);
  if v->'changes' = '[]'::jsonb then
    raise exception 'the bank account changes nothing' using errcode = '22023';
  end if;
  return jsonb_build_object('kind', 'payment_instructions', 'changes', v->'changes', 'revision', v->>'revision');
end;
$fn$;
revoke execute on function public.mcp_target_set_payment_instructions(uuid, jsonb) from public, anon, authenticated;

-- Runs only after the person confirmed the exact change. The write is the
-- app's (the column of the workspace row); this definer is not limited by the
-- column guard, so manageIntegrations is asked again for the person, and the
-- money functionality. The answer says that the account changed, never what
-- it became.
create or replace function public.mcp_op_set_payment_instructions(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v jsonb;
  v_actor uuid;
  v_owner uuid;
  v_before text;
  v_after text;
begin
  begin
    perform public.mcp_setup_arguments(p_args, array['workspace_id', 'request_id',
      'iban', 'bic', 'bank_name', 'account_number', 'bank_code', 'qr_iban']);
  exception when sqlstate 'DKS01' then
    return public.mcp_outcome('denied', null, 'secret_in_app_only');
  end;
  if not public.has_permission(c.workspace_id, 'manageIntegrations') then
    return public.mcp_outcome('denied', null, 'forbidden');
  end if;
  if not public.feature_effective(c.workspace_id, 'moneyTab') then
    return public.mcp_outcome('denied', null, 'not_exposed');
  end if;
  v := public.payment_instructions_plan(c.workspace_id, p_args);
  if v->'changes' = '[]'::jsonb then
    raise exception 'the bank account changes nothing' using errcode = '22023';
  end if;
  select m.id into v_actor from public.members m
   where m.workspace_id = c.workspace_id and m.user_id = auth.uid() and m.status = 'active';
  select m.id into v_owner from public.members m
   where m.workspace_id = c.workspace_id and m.is_owner and m.status = 'active'
   order by m.joined_at, m.id limit 1;
  update public.workspaces w
     set payment_instructions = coalesce(w.payment_instructions, '{}'::jsonb)
       || (select jsonb_object_agg(ch->>'field', ch->'to') from jsonb_array_elements(v->'changes') ch)
   where w.id = c.workspace_id;
  select ch->>'from', ch->>'to' into v_before, v_after
    from jsonb_array_elements(v->'changes') ch where ch->>'field' = 'iban';
  insert into public.events (workspace_id, type, action, actor_member_id, subject_member_id, payload, status)
  values (c.workspace_id, 'payment_instructions_change', 'modified', v_actor, coalesce(v_owner, v_actor),
    jsonb_build_object(
      'fields', (select jsonb_agg(ch->>'field') from jsonb_array_elements(v->'changes') ch),
      'iban_before', right(replace(coalesce(v_before, ''), ' ', ''), 4),
      'iban_after', right(replace(coalesce(v_after, ''), ' ', ''), 4)),
    'applied');
  return public.mcp_outcome('completed', jsonb_build_object('changed', true));
end;
$fn$;
revoke execute on function public.mcp_op_set_payment_instructions(public.mcp_call_context, jsonb) from public, anon, authenticated;

notify pgrst, 'reload schema';

select public.set_deskilo_schema_version(639);
